    weight: 7,
    once: true,
    text: {
      fr: ["Saut en parachute en tandem, à 4 000 mètres. Ton moniteur, Dylan, a 22 ans, un man bun et sent le Monster. Il te demande si tu as « des problèmes cardiaques ». Tu as menti sur le formulaire.", "Tu es au bord de la porte de l'avion. Le vent te fait claquer les joues comme des drapeaux. Ton dentier tremble. La famille filme au sol avec un zoom."],
      en: ["Tandem skydive from 13,000 feet. Your instructor, Dylan, is 22, has a man bun and smells of energy drink. He asks if you have 'heart problems'. You lied on the form.", "You're standing at the airplane door. The wind flaps your cheeks like flags. Your dentures are rattling. The family is filming from the ground with a zoom lens."],
    },
    choices: [
      {
        label: { fr: 'Sauter en criant', en: 'Jump, screaming' },
        out: [
          { w: 5, text: { fr: "J'ai sauté en hurlant « GÉRONIMOOO ! ». Mon dentier s'est envolé à 200 km/h. Il est quelque part dans un champ de betteraves. Je n'ai jamais été aussi vivant{|e}. La vidéo montre surtout mes gencives.", en: "I jumped yelling 'GERONIMOOO!'. My dentures flew off at 120 mph. They're somewhere in a beet field. I've never felt more alive. The video mostly shows my gums." }, fx: { happy: 18, health: -2, counter: 'bucket' }, mood: 'party' },
          { w: 2, text: { fr: "Atterrissage raté. On a labouré un champ sur 30 mètres. Dylan a perdu son chignon, moi ma deuxième hanche. Mais j'ai coché la case. Au crayon, depuis le lit d'hôpital.", en: "Botched landing. We plowed a field for 30 yards. Dylan lost his man bun, I lost my second hip. But I ticked the box. In pencil, from my hospital bed." }, fx: { happy: 8, health: -12, counter: 'bucket' }, mood: 'proud' },
          { w: 1, rating: 2, text: { fr: "J'ai admiré la vue si fort que mon cœur a lâché à 3 000 mètres. Dylan a atterri avec un passager mort qui souriait jusqu'aux oreilles. Les betteraves ont été épargnées. Pas Dylan, qui a démissionné.", en: "I admired the view so hard my heart quit at 10,000 feet. Dylan landed with a dead passenger grinning ear to ear. The beets were spared. Dylan wasn't — he quit." }, fx: { die: { fr: "en chute libre, à {age} ans, le sourire aux lèvres et sans dentier", en: "in free fall, aged {age}, smiling and toothless" } }, mood: 'shock' },
        ],
      },
      { label: { fr: 'Se dégonfler', en: 'Chicken out' }, text: { fr: "Je me suis agrippé{|e} au siège en hurlant « JE VEUX MA MÈRE ». Ma mère est morte en 1987. L'avion a atterri. J'ai acheté le t-shirt « J'ai sauté » quand même.", en: "I clung to the seat screaming 'I WANT MY MOM'. My mom died in 1987. The plane landed. I bought the 'I jumped' T-shirt anyway." }, fx: { happy: -4 } },
    ],
