    chainOnly: true,
    scene: { place: 'studio', mood: 'shock', prop: 'books', fx: 'confetti' },
    when: { flag: 'ol_memoir' },
    text: {
      fr: ["Tes mémoires sont publiés par une petite maison d'édition locale. Tirage : 300 exemplaires. Dans la famille, tout le monde l'a lu en une nuit. Le téléphone n'arrête pas de sonner.", "Ton livre est en vitrine de la librairie de {city}. Ta sœur a lu le chapitre sur son premier mari. Elle arrive. Elle a l'air de quelqu'un qui a lu le chapitre sur son premier mari."],
      en: ["Your memoirs are published by a small local press. Print run: 300 copies. The whole family read it in one night. The phone won't stop ringing.", "Your book is in the window of the {city} bookshop. Your sister read the chapter about her first husband. She's coming over. She looks like someone who read the chapter about her first husband."],
    },
    choices: [
      {
        label: { fr: 'Faire une tournée de dédicaces', en: 'Do a book tour' },
        out: [
          { w: 3, text: { fr: "J'ai fait une tournée de dédicaces dans trois supermarchés et une maison de retraite. 41 livres vendus, dont 12 à moi-même. Une dame m'a dit que j'avais « une plume ». Je l'ai épousée du regard.", en: "I did a signing tour of three supermarkets and a retirement home. 41 books sold, 12 to myself. A lady said I had 'a way with words'. I married her with my eyes." }, fx: { happy: 10, fame: 3, money: 300, unflag: 'ol_memoir' }, mood: 'proud' },
          { w: 1, text: { fr: "Un influenceur littéraire a lu le chapitre 12 en live. Le livre est devenu culte. Réédition nationale. Plateau télé. Tonton Michel a porté plainte. J'ai gagné plus d'argent qu'en 40 ans de carrière.", en: "A book influencer read chapter 12 live. The book went cult. National reprint. TV appearance. Uncle Mike sued. I earned more than in 40 years of work." }, fx: { happy: 16, fame: 12, money: 25000, followers: 20000, unflag: 'ol_memoir', visual: 'money' }, mood: 'party' },
        ],
      },
      { label: { fr: 'Racheter tous les exemplaires', en: 'Buy back every copy' }, text: { fr: "Pris de remords, j'ai racheté les 300 exemplaires et je les ai brûlés dans le jardin. Il en reste un, chez ma sœur. Elle s'en sert pour me faire chanter. Je lui fais ses courses.", en: "Gripped by remorse, I bought all 300 copies and burned them in the yard. One remains, at my sister's. She blackmails me with it. I do her grocery shopping now." }, fx: { money: -3000, happy: -4, karma: 3, unflag: 'ol_memoir', visual: 'fire' } },
    ],
